"use client";

import { Hero } from "@/components/ui/animated-hero";
import { SiteNav } from "@/components/ui/site-nav";
import { ProcessSection } from "@/components/ui/process-section";
import { StatsStrip } from "@/components/ui/stats-strip";
import { CinematicFooter } from "@/components/ui/motion-footer";
import workSlugs from "@/lib/work-images.generated.json";

const BASE = process.env.NEXT_PUBLIC_BASE_PATH ?? "";

// Generated by scripts/optimize-images.mjs from assets/thumbnails-src/ — do
// not hand-edit; drop new source images in that folder and re-run the script
// (it also runs automatically before every build).
const MARQUEE_IMAGES = (workSlugs as string[]).map((slug) => `${BASE}/work/${slug}.webp`);

export default function Home() {
  return (
    <main>
      <SiteNav />

      {/* HERO */}
      <section id="inicio" className="relative min-h-screen overflow-hidden">
        <Hero images={MARQUEE_IMAGES} />
      </section>

      <ProcessSection />

      <StatsStrip />

      {/* FOOTER */}
      <div id="contacto">
        <CinematicFooter />
      </div>
    </main>
  );
}
